module.exports = function yn(value, options) {
  options = options || {};

  if (value === undefined || value === null) {
    return options.default;
  }

  if (typeof value === 'boolean') {
    return value;
  }

  if (typeof value === 'string') {
    value = value.trim().toLowerCase();
    if (value === 'true' || value === 'y' || value === 'yes' || value === '1') {
      return true;
    }
    if (value === 'false' || value === 'n' || value === 'no' || value === '0') {
      return false;
    }
  }

  return options.default;
};
